mapper.select:
select t1.*
from TBL_CEA_OFFICE_EXPENSES t1
where 1=1 and (t1.creator = #{param.creator}

   or t1.creator in (SELECT DISTINCT STAFFID FROM TBL_USER_ORGRELATION WHERE DEPTID IN (${param.getDeptIds}))
)

    and t1.SUPPLYBELONGGROUPNAME like concat('%',concat(#{param.supplyBelongGroupName},'%'))


    and t1.OFFICEEXPENSESTIME >= #{param.officeExpensesTimeStart}


    and t1.OFFICEEXPENSESTIME < #{param.officeExpensesTimeEnd}

order by t1.id desc
